SaxonProcessor * processor = new Saxon\SaxonProcessor(false);
Xslt30Processor * xslt = processor->newXslt30Transformer();

XdmAtomicValue * value =processor->makeStringValue("Hello to you");
if(xdmvaluex !=NULL){
  cerr<<"xdmvaluex ok"<<endl;
}
XsltExecutable * executable = xslt->compileFromFile("foo.xsl");
if(executable == nullptr) {
  if(proc->exceptionOccurred()) {
      cout << "Error : " << proc->getErrorMessage() <<endl;

  }
  return;
}
executable->setInitialMatchSelectionAsFile("foo.xml");
executable->setParameter("a-param", (XdmValue *) value);

const char *result = executable->applyTemplatesReturningString();
if(result != NULL) {
  cerr<<result<<endl;
} else {
  cerr<<"Result is NULL"<<endl;
}
executable->clearParameters();
executable->clearProperties();
delete executable;
delete result;
delete value;

SaxonProcessor * processor = new SaxonProcessor(false);
Xslt30Processor * xslt = processor->newXslt30Transformer();
xslt->setInitialMatchSelectionAsFile("cat.xml");
XsltExecutable * executable = xslt->compileFromFile("test.xsl");
const char * output = executable->applyTemplatesReturningString();
if(output !=NULL){
  cerr<< output<<endl;
}
XdmValue * values = new XdmValue(processor);
values->addXdmItem((XdmItem*)processor->makeIntegerValue(10));
values->addXdmItem((XdmItem*)processor->makeIntegerValue(5));
values->addXdmItem((XdmItem*)processor->makeIntegerValue(6));
values->addXdmItem((XdmItem*)processor->makeIntegerValue(7));
xslt->setParameter("values",(XdmValue *)values);
XdmNode * input = processor->parseXmlFromFile("cat.xml");

XsltExecutable * executable2 = xslt->compileFromFile("test2.xsl");
executable2->setInitialMatchSelection((XdmValue*)input);
const char * rootValue = executable2->callTemplateReturningString("main");
if(rootValue != NULL) {
  cerr<<rootValue<<endl;
} else {
  cerr<<"Result is NULL"<<endl;
}
xslt->clearParameters(true);
xslt->clearProperties();
delete executable;
delete executable2;

